def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    colors = [value for value in counts if value != background]
    marker = max(colors, key=lambda value: counts[value])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    top = min(r for r, c in points)
    bottom = max(r for r, c in points)
    left = min(c for r, c in points)
    right = max(c for r, c in points)
    out = [row[:] for row in grid]

    def fill(r, c):
        if out[r][c] == background:
            out[r][c] = 2

    # Connect markers within each row.
    for r in range(h):
        cols = [c for rr, c in points if rr == r]
        if len(cols) >= 4:
            for c in range(min(cols), max(cols) + 1):
                fill(r, c)
    # Complete the outer rectangular frame around the marker pattern.
    for c in range(left, right + 1):
        fill(top, c)
        fill(bottom, c)
    for r in range(top, bottom + 1):
        fill(r, left)
        fill(r, right)
    # Bridge one-cell vertical breaks between two adjacent runs.
    for c in range(w):
        for r in range(1, h - 1):
            if grid[r][c] == background and grid[r - 1][c] == marker and grid[r + 1][c] == marker:
                if r >= 2 and r + 2 < h and grid[r - 2][c] == marker and grid[r + 2][c] == marker:
                    fill(r, c)
    return out

